/* Platform guide, first journey, personal travel book and wardrobe. */
function visitCompanionMarkup(options={}){return `<span class="visit-companion ${options.small?'is-small':''}"><img src="assets/marten-helper.png" width="190" height="225" alt="Куница — помогающий спутник в Этноходе"></span>`}
const VISIT_TUTORIAL_STEPS=[
 {title:'Весь мир — на твоей карте',text:'Я — куница, твой спутник. Вместе будем ездить в гости к семьям разных народов России. Помогу найти путь! На карте можно приближать места, передвигаться и выбирать отметки. Нажми на золотой компас — так отмечено открытое приключение.',demo:'map'},
 {title:'Не все страницы открыты',text:'Светлые отметки с замком — будущие маршруты. Их истории ещё готовятся. Начать уже можно с Башкортостана!',demo:'locked'},
 {title:'Забирай открытия в рюкзак',text:'Рецепты, собранные узоры и новые слова остаются в твоей книге. Награды тоже не теряются: они живут в дневнике этого браузера.',demo:'bag'},
 {title:'Спрашивать — здорово',text:'Если что-то непонятно, открой проводника. Он поможет вспомнить материалы и разобраться в задании. Попробуй задать первый вопрос прямо сейчас.',demo:'ask'},
 {title:'Каждое открытие меняет тебя',text:'В путешествии ты узнаешь, как живут люди, что их объединяет и чем интересны их традиции. А за помощь новым друзьям получишь подарки для героя.',demo:'benefits'},
 {title:'Первая страница — Башкортостан',text:'Данияр ждёт тебя на Южном Урале. Вместе приготовим праздничное меню, соберём наряды, выучим первые слова и послушаем бабушкины истории. Отправляемся?',demo:'invite'}
];
function visitTutorialDemo(kind,u){if(kind==='map'||kind==='locked')return `<div class="visit-tutorial-map"><div class="visit-map-drawing" data-visit-minimap></div><span class="visit-demo-pin ${kind==='locked'?'locked':''}">${kidIcon(kind==='locked'?'lock':'compass')}</span><span class="visit-map-caption">${kind==='locked'?'Новые экспедиции появятся позже':'Башкортостан — маршрут открыт'}</span></div>`;if(kind==='bag')return `<div class="visit-tutorial-bag">${kidIcon('bag')}<span>${kidIcon('book')}</span><span>${kidIcon('leaf')}</span><span>${kidIcon('star')}</span></div>`;if(kind==='ask')return `<div class="visit-tutorial-ask">${visitCompanionMarkup()}<div><button class="btn secondary" data-tutorial-ask>Что мы будем делать в гостях?</button><p id="tutorialReply" role="status"></p></div></div>`;if(kind==='benefits')return `<div class="visit-tutorial-benefits"><div>${gameCharacter(u)}</div><span>${storyRewardIcon('burek')}</span><span>${storyRewardIcon('kurai')}</span></div>`;return `<div class="visit-tutorial-invite"><img src="assets/ural-postcard.jpg" alt="Река, лес и горы Южного Урала"><span>${kidIcon('compass')} Башкортостан</span></div>`}
function visitTutorialPage(u){const step=Math.min(5,Math.max(0,Number(u?.tutorialStep)||0)),item=VISIT_TUTORIAL_STEPS[step];return `<div class="visit-shell visit-tutorial" id="visitTutorial"><div class="visit-tutorial-top"><a class="game-text-link" href="#map">← На карту</a><div class="visit-tutorial-dots" aria-label="Шаг ${step+1} из 6">${VISIT_TUTORIAL_STEPS.map((_,i)=>`<span class="${i<=step?'done':''}" ${i===step?'aria-current="step"':''}></span>`).join('')}</div><button class="btn secondary" type="button" data-tutorial-skip>Пропустить знакомство</button></div><section class="visit-tutorial-card"><div class="visit-tutorial-art">${visitTutorialDemo(item.demo,u)}</div><div class="visit-tutorial-copy"><div class="visit-tutorial-guide">${visitCompanionMarkup({small:true})}</div><h2>${item.title}</h2><p>${item.text}</p><div class="visit-tutorial-actions">${step?'<button type="button" class="btn secondary" data-tutorial-back>← Назад</button>':''}<button class="kid-primary" type="button" data-tutorial-next>${step===5?'Открыть первую главу':'Дальше'} ${kidIcon('arrow')}</button></div></div></section><p class="visit-local-note">Знакомство займёт около минуты. Вернуться к нему можно из книги путешественника.</p></div>`}
function visitMiniMap(root){root.querySelectorAll('[data-visit-minimap]').forEach(target=>fetch('assets/russia-map.json').then(r=>r.json()).then(data=>{if(!target.isConnected)return;target.innerHTML=`<svg viewBox="0 0 1100 610" aria-hidden="true">${data.regions.map(r=>`<path d="${r.d}" fill="${r.id==='bashkortostan'?'#d6ad54':'#d0ddbf'}" stroke="#91a582" stroke-width=".6"/>`).join('')}</svg>`}).catch(()=>{target.innerHTML=kidIcon('compass')}))}
function wireVisitTutorial(u){const root=$('#visitTutorial');if(!root)return;visitMiniMap(root);root.querySelector('[data-tutorial-ask]')?.addEventListener('click',()=>{root.querySelector('#tutorialReply').textContent='Поможем приготовить угощение, украсим наряды и узнаем новые слова. Данияр пригласит нас на семейное застолье!';visitRecord(u,'question',{topic:'dialogue'})});const move=n=>{u.tutorialStep=Math.max(0,Math.min(5,(Number(u.tutorialStep)||0)+n));save();root.outerHTML=visitTutorialPage(u);wireVisitTutorial(u)};root.querySelector('[data-tutorial-back]')?.addEventListener('click',()=>move(-1));root.querySelector('[data-tutorial-next]').onclick=()=>{if((Number(u.tutorialStep)||0)<5){move(1);return}u.tutorialDone=true;u.tutorialStep=0;save();location.hash='book/bashkortostan'};root.querySelector('[data-tutorial-skip]').onclick=()=>{u.tutorialDone=true;save();location.hash='map'}}
function visitBookUnlocked(u){const s=u?.story||{};return {recipes:(typeof STORY_RECIPES!=='undefined'?STORY_RECIPES:[]).filter(r=>(s.cooking?.[r.id]?.length||0)>=3),patterns:[0,1].filter(i=>(s.outfits?.[i]?.length||0)>=3),words:(typeof VISIT_PHRASES!=='undefined'?VISIT_PHRASES:typeof STORY_WORDS!=='undefined'?STORY_WORDS:[]).filter((_,i)=>s.words?.includes(i)),legend:!!s.legendRead}}
function visitBookSection(u,region,tab){const unlocked=visitBookUnlocked(u),s=u.story||{};if(region!=='bashkortostan')return `<div class="visit-book-locked">${kidIcon('lock')}<h2>Эта глава ещё впереди</h2><p>Мы собираем истории и материалы для новой экспедиции. А в Башкортостан уже можно отправиться!</p><a class="kid-primary" href="#book/bashkortostan">Открыть Башкортостан ${kidIcon('arrow')}</a></div>`;if(tab==='recipes')return `<h2>Рецепты из путешествия</h2><p>Восстановленные страницы семейного меню Данияра.</p><div class="visit-collection-grid">${unlocked.recipes.map(r=>`<article class="visit-collection-card"><span>${kidIcon('book')}</span><h3>${r.name}</h3><p>${r.intro}</p><ol>${r.items.map(t=>`<li>${t}</li>`).join('')}</ol><small>${r.note}</small></article>`).join('')||visitEmptyBook('Рецепты пока не собраны','Помоги Данияру на кухне — и готовые карточки появятся здесь.')}</div>`;if(tab==='patterns')return `<h2>Твоя мастерская</h2><p>Собранные в игре наряды и узоры.</p><div class="visit-collection-grid">${unlocked.patterns.map(i=>`<article class="visit-collection-card visit-pattern-collected">${typeof visitPatternCostume==='function'?visitPatternCostume(i,6):typeof storyOutfitSvg==='function'?storyOutfitSvg(i,['body','collar','hem']):kidIcon('leaf')}<h3>${i===0?'Первый праздничный наряд':'Второй праздничный наряд'}</h3><p>Ты собрал его во время подготовки к празднику. Эскиз упрощён для игры.</p></article>`).join('')||visitEmptyBook('Мастерская ждёт тебя','Собери детали нарядов и заполни узор в истории Данияра.')}</div>`;if(tab==='stories')return `<h2>Истории за семейным столом</h2><div class="visit-collection-grid">${(s.dinnerDone||[]).map(i=>`<article class="visit-collection-card"><h3>${VISIT_TABLE_SCENES[i].title}</h3><p>${VISIT_TABLE_SCENES[i].text}</p></article>`).join('')||visitEmptyBook('Семья ещё ждёт тебя','После застолья рассказы останутся здесь.')}</div>`;if(tab==='words')return `<h2>Твои первые слова</h2><p>Можно вернуться к ним перед следующей встречей. Записи и переводы: <a href="https://basic.bashlang.ru/vocabulary/topic/1/" target="_blank" rel="noopener">Интерактивный башкирский</a>. В записи знакомства звучит пример с именем Айнур.</p><div class="visit-word-cards">${unlocked.words.map(w=>`<article><strong>${w.word}</strong><span>${w.meaning}</span><small>Примерно: ${w.say||''}</small><button class="btn secondary" data-phrase-audio="${VISIT_PHRASES.indexOf(w)}">Послушать</button><p class="visit-audio-status" role="status"></p></article>`).join('')||visitEmptyBook('Словарик пока пуст','Выучи пять фраз для застолья — и они сохранятся здесь.')}</div>`;if(tab==='legend')return unlocked.legend?`<article class="visit-collected-legend"><span>${kidIcon('book')}</span><h2>«Урал-батыр»</h2><p>Башкирский народный эпос передавали устно сэсэны. Это художественная история о жизни, ответственности и выборе героя.</p><p>В сказании герой выбирает благо людей и природы. Ты открыл все шесть иллюстрированных страниц.</p>${VISIT_EPIC_FRAMES.map((f,i)=>`<section><div class="visit-legend-picture" style="--epic-x:${i%2?100:0}%;--epic-y:${Math.floor(i/2)*50}%" role="img" aria-label="${f[0]}"></div><h3>${f[0]}</h3><p>${f[1]}</p></section>`).join('')}<a class="game-text-link" href="#story">Вернуться к истории →</a></article>`:visitEmptyBook('Легенда ещё не услышана','Бабушка Данияра предлагает послушать её ближе к концу истории. Это необязательная остановка.');return `<div class="visit-book-overview"><div class="visit-book-contour" data-visit-contour>${kidIcon('compass')}</div><div><h2>Башкортостан</h2><p class="visit-native-name" lang="ba">Башҡортостан</p><p>Южный Урал и Предуралье. Столица — Уфа. Здесь живут люди разных народов, языков и семейных традиций.</p><p>Данияр приглашает тебя помочь с подготовкой к празднику. Каждое открытие останется на страницах этой книги.</p></div><figure><img src="assets/ural-postcard.jpg" alt="Иллюстрированный пейзаж Южного Урала"><figcaption>Горы, лес и река — место нашей первой истории</figcaption></figure><div class="visit-book-enter"><a class="kid-primary" href="#story">${s.completed?'Вернуться в историю':'Войти в главу'} ${kidIcon('arrow')}</a><a class="game-text-link" href="#map">Выбрать другое место →</a></div></div>`}
function visitEmptyBook(title,text){return `<div class="visit-book-empty">${kidIcon('lock')}<h3>${title}</h3><p>${text}</p><a class="btn secondary" href="#story">Продолжить историю ${kidIcon('arrow')}</a></div>`}
function visitBookPage(u,arg){const region=['bashkortostan','tatarstan','dagestan','yakutia'].includes(arg)?arg:'bashkortostan',names={bashkortostan:'Башкортостан',tatarstan:'Татарстан',dagestan:'Дагестан',yakutia:'Якутия'},tab='overview';return `<div class="visit-shell visit-book" id="visitBook" data-region="${region}"><div class="visit-book-toolbar"><a class="game-text-link" href="#map">← На карту</a><a class="game-text-link" href="#wardrobe">Гардероб ${kidIcon('bag')}</a><a class="game-text-link" href="#guide">Спросить спутника</a><a class="game-text-link" href="#tutorial">Знакомство со спутником ${kidIcon('help')}</a></div><nav class="visit-book-regions" aria-label="Главы книги">${Object.entries(names).map(([id,name])=>`<a class="${region===id?'active':''}" href="#book/${id}">${id==='bashkortostan'?kidIcon('book'):kidIcon('lock')}${name}</a>`).join('')}</nav><div class="visit-book-spread"><nav class="visit-book-tabs" aria-label="Страницы главы">${[['overview','О регионе'],['recipes','Рецепты'],['patterns','Узоры и наряды'],['words','Словарик'],['stories','Рассказы семьи'],['legend','Легенда']].map(([id,name])=>`<button class="btn secondary ${id===tab?'active':''}" data-book-tab="${id}" type="button" aria-pressed="${id===tab}">${name}</button>`).join('')}</nav><section class="visit-book-page" id="visitBookPage">${visitBookSection(u,region,tab)}</section></div>${region==='bashkortostan'?`<div class="visit-book-intro" id="visitBookIntro"><div class="visit-turning-book"><span></span><span></span>${kidIcon('book')}</div><p>Открываем твою историю…</p><button type="button" class="btn secondary" data-book-skip>Открыть сразу</button></div>`:''}</div>`}
function wireVisitBook(u){const root=$('#visitBook');if(!root)return;const region=root.dataset.region;function contour(){root.querySelectorAll('[data-visit-contour]').forEach(target=>fetch('assets/russia-map.json').then(r=>r.json()).then(data=>{if(!target.isConnected)return;const r=data.regions.find(r=>r.id==='bashkortostan');if(!r)return;target.innerHTML=`<svg role="img" aria-label="Контур Башкортостана"><path d="${r.d}" fill="#d6b669" stroke="#7c9562" stroke-width="1"/></svg>`;const svg=target.querySelector('svg'),b=svg.querySelector('path').getBBox();svg.setAttribute('viewBox',`${b.x-6} ${b.y-6} ${b.width+12} ${b.height+12}`)}).catch(()=>{}))}contour();root.querySelectorAll('[data-book-tab]').forEach(button=>button.onclick=()=>{root.querySelectorAll('[data-book-tab]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});$('#visitBookPage').innerHTML=visitBookSection(u,region,button.dataset.bookTab);contour();root.querySelectorAll('[data-phrase-audio]').forEach(b=>b.onclick=()=>visitPlayPhrase(+b.dataset.phraseAudio))});const intro=root.querySelector('#visitBookIntro');if(intro){const finish=()=>{intro.remove();u.bookOpened=true;save()};root.querySelector('[data-book-skip]').onclick=finish;if(matchMedia('(prefers-reduced-motion: reduce)').matches||u.bookOpened)finish();else setTimeout(()=>{if(intro.isConnected)finish()},2000)}}
function visitWardrobePage(u){const c=typeof characterData==='function'?characterData(u):u.character||{outfit:'green'},hat=u.rewards?.includes('burek'),kurai=u.rewards?.includes('kurai');return `<div class="visit-shell visit-wardrobe" id="visitWardrobe"><section class="visit-wardrobe-preview"><div class="visit-wardrobe-stage">${gameCharacter(u)}</div><h2>${esc(u.nick)}</h2><p>${u.equippedHat==='burek'?'Бүрек надет — можно на праздник!':'Собери образ для следующего путешествия.'}</p><a class="btn secondary" href="#character/edit">Изменить персонажа</a></section><section class="visit-wardrobe-controls"><h2>Твой гардероб</h2><p>Цвет одежды можно менять в любое время. Подарки из путешествий откроют новые детали.</p><fieldset><legend>Цвет одежды</legend><div class="visit-clothes-colors">${[['green','Лесной'],['red','Ягодный'],['blue','Небесный']].map(([id,name])=>`<button type="button" class="btn secondary ${c.outfit===id?'active':''}" data-wardrobe-color="${id}" aria-pressed="${c.outfit===id}"><i class="${id}"></i>${name}</button>`).join('')}</div></fieldset><fieldset><legend>Праздничный подарок</legend><div class="visit-wardrobe-item ${hat?'earned':'locked'}"><span>${storyRewardIcon('burek')}</span><div><h3>Бүрек</h3><p>${hat?'Подарок Данияра за помощь с праздником.':'Откроется после завершения истории Башкортостана.'}</p>${hat?`<button type="button" class="kid-primary" data-wardrobe-hat aria-pressed="${u.equippedHat==='burek'}">${u.equippedHat==='burek'?'Снять шапку':'Надеть шапку'}</button>`:'<a class="btn secondary" href="#story">Продолжить историю →</a>'}</div></div></fieldset><fieldset><legend>Что в рюкзаке</legend><div class="visit-backpack"><span>${kidIcon('bag')}</span><div><h3>${kurai?'Значок «Курай»':'Место для будущих находок'}</h3><p>${kurai?'Значок прикреплён к рюкзаку твоего героя.':'Пройди первую главу — и здесь появится подарок на память.'}</p>${kurai?`<span class="visit-backpack-badge">${storyRewardIcon('kurai')}</span>`:''}</div></div></fieldset><div class="visit-wardrobe-actions"><a class="kid-primary" href="#map">В путешествие ${kidIcon('arrow')}</a><a class="game-text-link" href="#book/bashkortostan">Открыть книгу →</a></div><p class="visit-wardrobe-status" role="status">Все изменения сохраняются автоматически.</p></section></div>`}
function wireVisitWardrobe(u){const root=$('#visitWardrobe');if(!root)return;const refresh=()=>{save();root.outerHTML=visitWardrobePage(u);wireVisitWardrobe(u)};root.querySelectorAll('[data-wardrobe-color]').forEach(b=>b.onclick=()=>{u.character=Object.assign({},typeof characterData==='function'?characterData(u):u.character,{outfit:b.dataset.wardrobeColor});refresh()});root.querySelector('[data-wardrobe-hat]')?.addEventListener('click',()=>{if(!u.rewards?.includes('burek'))return;u.equippedHat=u.equippedHat==='burek'?null:'burek';refresh()})}
